import XCTest
import GRDB

/// Tests for speaker re-identification bugs:
/// Bug 1: Old auto-generated speaker (S1) remains in meeting_speakers after re-identification
/// Bug 2: Speaker appears twice after partial re-identification
final class SpeakerReidentificationTests: XCTestCase {

    private var db: DatabaseManager!
    private var speakerRepo: SpeakerRepository!
    private var meetingRepo: MeetingRepository!

    override func setUp() async throws {
        db = try makeTestDB()
        speakerRepo = SpeakerRepository(db: db)
        meetingRepo = MeetingRepository(db: db)
    }

    // MARK: - Bug 1: Old speaker not cleaned up after rename

    /// Simulates the pipeline creating segments without speakerId, then user re-identifying
    /// speaker_1 as existing speaker "Alice". The old speaker_1 should be removed.
    func testRenameSpeaker_oldAutoGeneratedSpeakerRemoved() async throws {
        let meeting = makeMeeting()
        try await meetingRepo.save(meeting)

        // Pipeline creates auto-generated speaker and assigns to meeting
        let autoSpeaker = makeSpeaker(name: "speaker_1")
        try await speakerRepo.save(autoSpeaker)
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: meeting.id, speakerId: autoSpeaker.id, diarizationLabel: "speaker_1"
        )

        // Pipeline creates segments WITHOUT speakerId (only speakerLabel)
        let seg1 = makeSegment(meetingId: meeting.id, speakerLabel: "speaker_1", startTime: 0, endTime: 5, text: "Hello")
        let seg2 = makeSegment(meetingId: meeting.id, speakerLabel: "speaker_1", startTime: 5, endTime: 10, text: "World")
        try await meetingRepo.saveSegments([seg1, seg2])

        // User creates/picks existing speaker "Alice"
        let alice = makeSpeaker(name: "Alice")
        try await speakerRepo.save(alice)

        // Simulate renameSpeaker flow:
        // 1. Assign Alice to meeting
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: meeting.id, speakerId: alice.id, diarizationLabel: "speaker_1"
        )
        // 2. Update all segments from speaker_1 → Alice
        try await meetingRepo.renameSpeakerInMeeting(
            meetingId: meeting.id, oldLabel: "speaker_1", newLabel: "Alice", speakerId: alice.id
        )
        // 3. Cleanup old speaker (this is where the bug is — speakerId was nil on segment)
        try await speakerRepo.cleanupOrphanedMeetingSpeakers(meetingId: meeting.id)

        // Assert: only Alice should remain in meeting_speakers
        let speakers = try await speakerRepo.speakersForMeeting(meeting.id)
        XCTAssertEqual(speakers.count, 1, "Only Alice should remain, speaker_1 should be cleaned up")
        XCTAssertEqual(speakers[0].speaker.nameEn, "Alice")

        // Assert: auto-generated speaker should be deleted entirely (no other meetings reference it)
        let deletedSpeaker = try await speakerRepo.find(autoSpeaker.id)
        XCTAssertNil(deletedSpeaker, "Orphaned auto-generated speaker should be deleted")
    }

    // MARK: - Bug 2: Duplicate speaker after partial identification

    /// Simulates: user reassigns one segment of speaker_1 to Alice, then renames remaining.
    /// Speaker_1 should not appear twice.
    func testPartialReidentification_noDuplicateSpeakers() async throws {
        let meeting = makeMeeting()
        try await meetingRepo.save(meeting)

        // Pipeline creates auto-generated speaker
        let autoSpeaker = makeSpeaker(name: "speaker_1")
        try await speakerRepo.save(autoSpeaker)
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: meeting.id, speakerId: autoSpeaker.id, diarizationLabel: "speaker_1"
        )

        // Pipeline creates 3 segments without speakerId
        let seg1 = makeSegment(meetingId: meeting.id, speakerLabel: "speaker_1", startTime: 0, endTime: 5, text: "A")
        let seg2 = makeSegment(meetingId: meeting.id, speakerLabel: "speaker_1", startTime: 5, endTime: 10, text: "B")
        let seg3 = makeSegment(meetingId: meeting.id, speakerLabel: "speaker_1", startTime: 10, endTime: 15, text: "C")
        try await meetingRepo.saveSegments([seg1, seg2, seg3])

        let alice = makeSpeaker(name: "Alice")
        try await speakerRepo.save(alice)

        // Step 1: Reassign single segment to Alice (reassignSegmentSpeaker flow)
        let segments = try await meetingRepo.segments(for: meeting.id)
        try await meetingRepo.updateSegmentSpeaker(
            id: segments[0].id!, speakerId: alice.id, speakerLabel: "Alice"
        )
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: meeting.id, speakerId: alice.id, diarizationLabel: nil
        )
        // Don't cleanup yet — we still have unidentified segments

        // Step 2: Rename remaining speaker_1 segments to Alice (renameSpeaker flow)
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: meeting.id, speakerId: alice.id, diarizationLabel: "speaker_1"
        )
        try await meetingRepo.renameSpeakerInMeeting(
            meetingId: meeting.id, oldLabel: "speaker_1", newLabel: "Alice", speakerId: alice.id
        )
        try await speakerRepo.cleanupOrphanedMeetingSpeakers(meetingId: meeting.id)

        // Assert: only Alice should remain, no duplicates
        let finalSpeakers = try await speakerRepo.speakersForMeeting(meeting.id)
        XCTAssertEqual(finalSpeakers.count, 1, "Only Alice should remain after full re-identification")
        XCTAssertEqual(finalSpeakers[0].speaker.nameEn, "Alice")
    }

    // MARK: - People the user named are not orphans

    /// The cleanup runs after every speaker edit in a meeting window. A
    /// confirmed person whose only meeting was deleted or reprocessed, and the
    /// owner right after voice enrollment, have no meeting to their name — and
    /// were deleted with their name, color and voiceprint by an unrelated edit.
    func testCleanupOrphaned_keepsConfirmedSpeakersAndMe() async throws {
        let meeting = makeMeeting()
        try await meetingRepo.save(meeting)
        let confirmed = makeSpeaker(name: "Alice")
        try await speakerRepo.save(confirmed)
        try await speakerRepo.confirmSpeaker(confirmed.id)
        let me = makeSpeaker(name: "Me", isMe: true)
        try await speakerRepo.save(me)
        let stray = makeSpeaker(name: "speaker_7")
        try await speakerRepo.save(stray)

        try await speakerRepo.cleanupOrphanedMeetingSpeakers(meetingId: meeting.id)

        let confirmedAfter = try await speakerRepo.find(confirmed.id)
        let meAfter = try await speakerRepo.find(me.id)
        let strayAfter = try await speakerRepo.find(stray.id)
        XCTAssertNotNil(confirmedAfter, "a confirmed speaker without meetings must survive")
        XCTAssertNotNil(meAfter, "the owner without meetings must survive")
        XCTAssertNil(strayAfter, "an unconfirmed leftover is still removed")
    }

    // MARK: - Edge case: shared speaker preserved

    /// When cleaning up orphaned speakers, speakers shared with other meetings must be preserved.
    func testCleanupOrphaned_sharedSpeakerPreserved() async throws {
        let m1 = makeMeeting(title: "Meeting 1")
        let m2 = makeMeeting(title: "Meeting 2")
        try await meetingRepo.save(m1)
        try await meetingRepo.save(m2)

        let autoSpeaker = makeSpeaker(name: "speaker_1")
        try await speakerRepo.save(autoSpeaker)

        // speaker_1 is in both meetings
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: m1.id, speakerId: autoSpeaker.id, diarizationLabel: "speaker_1"
        )
        try await speakerRepo.assignSpeakerToMeeting(
            meetingId: m2.id, speakerId: autoSpeaker.id, diarizationLabel: "speaker_1"
        )

        // speaker_1 has segments only in m2
        let seg = makeSegment(meetingId: m2.id, speakerId: autoSpeaker.id, speakerLabel: "speaker_1", text: "Hello")
        try await meetingRepo.saveSegments([seg])

        // Cleanup m1 — should remove meeting_speakers link for m1 but keep the speaker (used in m2)
        try await speakerRepo.cleanupOrphanedMeetingSpeakers(meetingId: m1.id)

        let m1Speakers = try await speakerRepo.speakersForMeeting(m1.id)
        XCTAssertEqual(m1Speakers.count, 0, "speaker_1 should be removed from m1 (no segments)")

        let m2Speakers = try await speakerRepo.speakersForMeeting(m2.id)
        XCTAssertEqual(m2Speakers.count, 1, "speaker_1 should remain in m2 (has segments)")

        // Speaker itself should still exist
        let speaker = try await speakerRepo.find(autoSpeaker.id)
        XCTAssertNotNil(speaker, "Speaker should not be deleted — still used in m2")
    }
}
